/** The media sizes supported by the printer. Supports standard size names for ISO and ANSI media sizes. For the list of supported values, see mediaSizes values. */
export type PrinterCapabilitiesMediaSizesList = Array<string | null>;
/** The media types supported by the printer. */
export type PrinterCapabilitiesMediaTypesList = Array<string | null>;
/** The presentation directions supported by the printer. Supported values are described in the following table. */
export type PrinterCapabilitiesMultipageLayoutsList = Array<
  PrintMultipageLayout | (string & {}) | null
>;
/** The print orientations supported by the printer. Valid values are described in the following table. */
export type PrinterCapabilitiesOrientationsList = Array<PrintOrientation | (string & {}) | null>;
/** The printer's supported output bins (trays). */
export type PrinterCapabilitiesOutputBinsList = Array<string | null>;
/** Supported number of Input Pages to impose upon a single Impression. */
export type PrinterCapabilitiesPagesPerSheetList = Array<number | null>;
/** The print qualities supported by the printer. */
export type PrinterCapabilitiesQualitiesList = Array<PrintQuality | (string & {}) | null>;
/** A list of supported right margins(in microns) for the printer. */
export type PrinterCapabilitiesRightMarginsList = Array<number | null>;
/** Supported print scalings. */
export type PrinterCapabilitiesScalingsList = Array<PrintScaling | (string & {}) | null>;
/** A list of supported top margins(in microns) for the printer. */
export type PrinterCapabilitiesTopMarginsList = Array<number | null>;
export interface PrinterCapabilities {
  /** A list of supported bottom margins(in microns) for the printer. */
  bottomMargins?: PrinterCapabilitiesBottomMarginsList | undefined;
  /** True if the printer supports collating when printing muliple copies of a multi-page document; false otherwise. */
  collation?: boolean | null | undefined;
  /** The color modes supported by the printer. Valid values are described in the following table. */
  colorModes?: PrinterCapabilitiesColorModesList | undefined;
  /** A list of supported content (MIME) types that the printer supports. It is not guaranteed that the Universal Print service supports printing all of these MIME types. */
  contentTypes?: PrinterCapabilitiesContentTypesList | undefined;
  /** The range of copies per job supported by the printer. */
  copiesPerJob?: IntegerRange | null | undefined;
  /** The list of print resolutions in DPI that are supported by the printer. */
  dpis?: PrinterCapabilitiesDpisList | undefined;
  /** The list of duplex modes that are supported by the printer. Valid values are described in the following table. */
  duplexModes?: PrinterCapabilitiesDuplexModesList | undefined;
  /** The list of feed orientations that are supported by the printer. */
  feedOrientations?: PrinterCapabilitiesFeedOrientationsList | undefined;
  /** Finishing processes the printer supports for a printed document. */
  finishings?: PrinterCapabilitiesFinishingsList | undefined;
  /** Supported input bins for the printer. */
  inputBins?: PrinterCapabilitiesInputBinsList | undefined;
  /** True if color printing is supported by the printer; false otherwise. Read-only. */
  isColorPrintingSupported?: boolean | null | undefined;
  /** True if the printer supports printing by page ranges; false otherwise. */
  isPageRangeSupported?: boolean | null | undefined;
  /** A list of supported left margins(in microns) for the printer. */
  leftMargins?: PrinterCapabilitiesLeftMarginsList | undefined;
  /** The media (for example, paper) colors supported by the printer. */
  mediaColors?: PrinterCapabilitiesMediaColorsList | undefined;
  /** The media sizes supported by the printer. Supports standard size names for ISO and ANSI media sizes. For the list of supported values, see mediaSizes values. */
  mediaSizes?: PrinterCapabilitiesMediaSizesList | undefined;
  /** The media types supported by the printer. */
  mediaTypes?: PrinterCapabilitiesMediaTypesList | undefined;
  /** The presentation directions supported by the printer. Supported values are described in the following table. */
  multipageLayouts?: PrinterCapabilitiesMultipageLayoutsList | undefined;
  /** The print orientations supported by the printer. Valid values are described in the following table. */
  orientations?: PrinterCapabilitiesOrientationsList | undefined;
  /** The printer's supported output bins (trays). */
  outputBins?: PrinterCapabilitiesOutputBinsList | undefined;
  /** Supported number of Input Pages to impose upon a single Impression. */
  pagesPerSheet?: PrinterCapabilitiesPagesPerSheetList | undefined;
  /** The print qualities supported by the printer. */
  qualities?: PrinterCapabilitiesQualitiesList | undefined;
  /** A list of supported right margins(in microns) for the printer. */
  rightMargins?: PrinterCapabilitiesRightMarginsList | undefined;
  /** Supported print scalings. */
  scalings?: PrinterCapabilitiesScalingsList | undefined;
  /** True if the printer supports scaling PDF pages to match the print media size; false otherwise. */
  supportsFitPdfToPage?: boolean | null | undefined;
  /** A list of supported top margins(in microns) for the printer. */
  topMargins?: PrinterCapabilitiesTopMarginsList | undefined;
  odataType?: string | undefined;
}
/** The default set of finishings to apply to print jobs. Valid values are described in the following table. */
export type PrinterDefaultsFinishingsList = Array<PrintFinishing | (string & {}) | null>;
export interface PrinterDefaults {
  /** The default color mode to use when printing the document. Valid values are described in the following table. */
  colorMode?: PrintColorMode | (string & {}) | null | undefined;
  /** The default content (MIME) type to use when processing documents. */
  contentType?: string | null | undefined;
  /** The default number of copies printed per job. */
  copiesPerJob?: number | null | undefined;
  /** The default resolution in DPI to use when printing the job. */
  dpi?: number | null | undefined;
  /** The default duplex (double-sided) configuration to use when printing a document. Valid values are described in the following table. */
  duplexMode?: PrintDuplexMode | (string & {}) | null | undefined;
  /** The default set of finishings to apply to print jobs. Valid values are described in the following table. */
  finishings?: PrinterDefaultsFinishingsList | undefined;
  /** The default fitPdfToPage setting. True to fit each page of a PDF document to a physical sheet of media; false to let the printer decide how to lay out impressions. */
  fitPdfToPage?: boolean | null | undefined;
  /** The default input bin that serves as the paper source. */
  inputBin?: string | null | undefined;
  /** The default media (such as paper) color to print the document on. */
  mediaColor?: string | null | undefined;
  /** The default media size to use. Supports standard size names for ISO and ANSI media sizes. Valid values are listed in the printerCapabilities topic. */
  mediaSize?: string | null | undefined;
  /** The default media (such as paper) type to print the document on. */
  mediaType?: string | null | undefined;
  /** The default direction to lay out pages when multiple pages are being printed per sheet. Valid values are described in the following table. */
  multipageLayout?: PrintMultipageLayout | (string & {}) | null | undefined;
  /** The default orientation to use when printing the document. Valid values are described in the following table. */
  orientation?: PrintOrientation | (string & {}) | null | undefined;
  /** The default output bin to place completed prints into. See the printer's capabilities for a list of supported output bins. */
  outputBin?: string | null | undefined;
  /** The default number of document pages to print on each sheet. */
  pagesPerSheet?: number | null | undefined;
  /** The default quality to use when printing the document. Valid values are described in the following table. */
  quality?: PrintQuality | (string & {}) | null | undefined;
  /** Specifies how the printer scales the document data to fit the requested media. Valid values are described in the following table. */
  scaling?: PrintScaling | (string & {}) | null | undefined;
  odataType?: string | undefined;
}
